import vue from "@vitejs/plugin-vue";
import sourcemaps from "rollup-plugin-sourcemaps2";
import commonjs from "vite-plugin-commonjs";
//#region src/configs/utils/createViteDevConfig.ts
function createViteDevConfig({ mode, command }) {
	const isProd = mode === "production";
	const isServe = command === "serve";
	const useSources = process.env.USE_SOURCES === "1" || isServe;
	return {
		base: "./",
		plugins: [vue(), ...isServe ? [commonjs({ filter: (id) => id.includes("node_modules") })] : []],
		build: {
			target: ["chrome140"],
			emptyOutDir: isProd,
			sourcemap: isProd,
			minify: isProd,
			rolldownOptions: { plugins: isProd ? [sourcemaps()] : [] }
		},
		resolve: { conditions: useSources ? ["sources"] : [] },
		define: { "import.meta.vitest": "undefined" }
	};
}
//#endregion
export { createViteDevConfig };
